import"./modulepreload-polyfill-B5Qt9EMX.js";import{m as r}from"./foundation-module-BgS6mBLm.js";import{h as n,p as s,i as e}from"./content-helpers-BfuPXrd1.js";const o='<div class="fm-flow" role="img" aria-label="Ultrasonic sensor input flows to threshold process, Bluetooth signal, and sound output"><span>distance input</span><b>→</b><span>threshold rule</span><b>→</b><span>Bluetooth signal</span><b>→</b><span>sound output</span></div>',i={id:"MOD-SENSOR-SYSTEMS-01",slug:"sensor-systems",version:"0.1.0",storageKey:"mod-sensor-systems-01-v0.1.0",mark:"µ7",shortTitle:"Sensor systems",title:"Sensor Systems, Thresholds, and Testing",gradeLabel:"Grades 7–8 Technology",classes:["7A","7B","8A","8B"],sections:[{id:"start",short:"Start",title:"Turn a sensor reading into an action",summary:"Trace input, process, signal, and output before building with a micro:bit or simulator.",minutes:5,html:`<section class="fm-opening"><div><p class="fm-label">Goal</p><h2>Every part needs a clear job</h2><p>A sensor system reads the environment, makes a decision, and produces an output. Testing proves whether that chain works reliably.</p></div>${o}</section><section class="fm-block"><p class="fm-label">Before you begin</p><h2>What you need and what you will save</h2><div class="fm-concept-grid"><div><h3>Know</h3><p>Input, process, output, conditions, and simple sensor readings.</p></div><div><h3>Use</h3><p>A computer, MakeCode, and assigned hardware or the simulator fallback.</p></div><div><h3>Plan</h3><p>An ultrasonic input, threshold process, Bluetooth signal, and sound output.</p></div><div><h3>Save</h3><p>The project file or share link, typed test table, system plan, and practice report.</p></div></div></section>`},{id:"system-learn",short:"Learn systems",title:"Trace input, process, signal, and output",summary:"Follow information through the whole system.",minutes:15,html:`<section class="fm-block"><p class="fm-label">Learn</p><h2>Information changes form as it moves</h2>${o}<div class="fm-concept-grid"><div><h3>Input</h3><p>The ultrasonic sensor reads distance.</p></div><div><h3>Process</h3><p>Code compares the reading with a threshold.</p></div><div><h3>Signal</h3><p>Bluetooth sends a message to another device.</p></div><div><h3>Output</h3><p>A sound or display warns the user.</p></div></div></section>`},s("system-practice","System practice","Practice tracing sensor systems","Identify each part and predict the result.",[e("Identify input","Which part provides a distance value?",["Ultrasonic sensor","Speaker","LED icon"],0,"Identify a sensor input","The ultrasonic sensor measures distance.","Input enters the program from a sensor or user."),e("Identify process","Which step decides whether the object is close enough?",["Compare distance with the threshold","Play the sound","Label the diagram"],0,"Identify processing","The comparison turns a reading into a decision.","Processing happens inside the program logic."),e("Identify signal","What can carry the alert from one device to another?",["Bluetooth message","Cardboard base","Project title"],0,"Identify communication","Bluetooth can transmit the alert between devices.","A signal transfers information."),e("Identify output","Which part communicates the warning to a person?",["Sound from the speaker","Distance value inside a variable","USB cable label"],0,"Identify output","The sound is an observable result of the system.","Output leaves the program for a user or device."),e("Trace failure","The sensor reads correctly, but no alert is sent. Which section should be checked next?",["Threshold and signal logic","Poster color","Group name"],0,"Trace the system chain","The failure occurs after input, so inspect the decision and message blocks.","Start at the last confirmed working step.")]),{id:"threshold-learn",short:"Learn thresholds",title:"Use a threshold rule",summary:"Predict boundary values and write an unambiguous condition.",minutes:15,html:'<section class="fm-block"><p class="fm-label">Rule</p><h2>If distance is greater than 18 cm, send ALERT</h2><p>A threshold is the boundary used to make a decision. Values on both sides of the boundary must be tested. The exact boundary value must also have a defined result.</p><div class="fm-concept-grid"><div><h3>17 cm</h3><p>Condition false.</p></div><div><h3>18 cm</h3><p>Condition false when the operator is &gt;.</p></div><div><h3>19 cm</h3><p>Condition true.</p></div></div></section>'},s("threshold-practice","Threshold practice","Practice threshold decisions","Predict outputs and choose useful tests.",[e("Below the boundary","Rule: if distance > 18, alert. What happens at 12 cm?",["No alert","Alert","The sensor is deleted"],0,"Evaluate a false condition","12 is not greater than 18.","Compare the reading with the operator exactly."),e("At the boundary","Rule: if distance > 18, alert. What happens at 18 cm?",["No alert","Alert","Bluetooth turns off forever"],0,"Evaluate the boundary","18 is equal to, not greater than, 18.","The operator is >, not >=."),e("Above the boundary","Rule: if distance > 18, alert. What happens at 25 cm?",["Alert","No alert","The value becomes 18"],0,"Evaluate a true condition","25 is greater than 18.","Check which side of the boundary the value falls on."),e("Test the rule","Which three readings best test the boundary?",["17, 18, and 19","2, 3, and 4","30, 40, and 50"],0,"Test around a threshold","The closest values below, at, and above the threshold expose boundary errors.","Test both sides and the exact limit."),e("Adjust carefully","The alert happens too late. What should the team change first?",["One threshold value, then repeat the same tests","Every block and wire at once","The project name"],0,"Control a test change","Changing one value preserves evidence about cause and effect.","One controlled change is easier to evaluate.")]),{id:"testing-learn",short:"Learn testing",title:"Build a useful test table",summary:"Record condition, expected result, actual result, and improvement.",minutes:12,html:'<section class="fm-block"><p class="fm-label">Test</p><h2>Reliable means the same condition gives the same result</h2><div class="fm-table-wrap"><table><thead><tr><th>Distance</th><th>Expected</th><th>Actual</th><th>Pass?</th></tr></thead><tbody><tr><td>17 cm</td><td>No alert</td><td>No alert</td><td>Yes</td></tr><tr><td>18 cm</td><td>No alert</td><td>Alert</td><td>No</td></tr><tr><td>19 cm</td><td>Alert</td><td>Alert</td><td>Yes</td></tr></tbody></table></div><p class="fm-note">The failed 18 cm trial points to a boundary-condition error.</p></section>'},s("testing-practice","Testing practice","Practice debugging with evidence","Use a test table to choose the next correction.",[e("Find the failed trial","Which trial in the example failed?",["18 cm","17 cm","19 cm"],0,"Read a test table","Expected and actual differ at 18 cm.","Compare the two result columns."),e("Name the likely cause","What is the most likely cause of an alert at exactly 18 cm?",["The code uses >= instead of >","The project has a title","The sensor uses centimetres"],0,"Infer from boundary evidence","Using >= makes the condition true at 18.","The failure occurs only at the boundary."),e("Check reliability","How can the team check that the correction is stable?",["Repeat the same three trials","Run one random trial","Change the threshold again"],0,"Retest consistently","Repeated controlled trials show whether the fix holds.","Keep the conditions the same after the correction."),e("Record an improvement","Which note is most useful?",["Changed >= to >; 18 cm now produces no alert in three trials","Fixed it","Made it better"],0,"Write evidence-based notes","The first note names the change, result, and repetition count.","Record enough detail to repeat the work."),e("Use a fallback","Hardware is unavailable. What preserves the objective?",["Use a labeled simulator and the same test table","Skip testing","Draw an unrelated poster"],0,"Use a comparable fallback","A simulator can test the same logic and evidence structure.","The fallback should preserve the system rule and tests.")]),{id:"system-record",short:"Record plan",title:"Record a sensor-system plan",summary:"Describe the fixed parts, threshold rule, and tests before building.",minutes:20,kind:"form",prompt:"Record a checkable system plan",fields:[{name:"purpose",label:"What should the system detect and communicate?",type:"textarea",rows:2},{name:"chain",label:"Name the input, process, signal, and output.",type:"textarea",rows:4},{name:"threshold",label:"Write the exact threshold condition and boundary result.",type:"textarea",rows:3},{name:"tests",label:"List three readings, expected results, and actual-result spaces.",type:"textarea",rows:5},{name:"fallback",label:"If hardware is unavailable, how will the labeled simulation preserve the test?",type:"textarea",rows:3}]},{id:"review",short:"Review",title:"Check the sensor plan before you submit",summary:"Review the system chain, boundary rule, test table, and saved evidence.",minutes:10,html:'<section class="fm-block"><p class="fm-label">Review</p><h2>Can another person repeat the test?</h2><ul class="fm-checklist"><li>The plan names the input, process, signal, and output.</li><li>The threshold rule includes the comparison operator and the result at the exact boundary.</li><li>The test table includes a value below, at, and above the threshold.</li><li>Expected and actual results are recorded separately.</li><li>The project file, share link, or labeled simulation opens on the computer.</li></ul></section><section class="fm-block"><p class="fm-label">Common mistakes</p><h2>Fix these before exporting</h2><div class="fm-concept-grid"><div><h3>Signal or output?</h3><p>Bluetooth carries the message. The sound communicates the warning to the user.</p></div><div><h3>Skipped boundary</h3><p>Test the exact threshold value as well as values on both sides.</p></div><div><h3>Changed everything</h3><p>Adjust one value or cause, then repeat the same trials.</p></div><div><h3>Vague result</h3><p>Record the distance, expected output, actual output, and pass result.</p></div></div></section><section class="fm-note"><strong>Next:</strong> revisit the practice page connected to any missing evidence. Then open History & export and download the report your teacher assigned.</section>'},n]};r(i);document.addEventListener("submit",t=>{if(t.target.id!=="fm-choice-form"||t.target.querySelector('input[name="answer"]:checked'))return;t.preventDefault(),t.stopImmediatePropagation();const a=t.target.querySelector('input[name="answer"]');a.setCustomValidity("Choose an answer before saving."),a.reportValidity(),a.addEventListener("change",()=>a.setCustomValidity(""),{once:!0})},!0);
